function fairTens(rolls: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i + 1 < rolls.length; i += 2) {
    const c = (rolls[i] - 1) * 7 + rolls[i + 1];
    if (c <= 40) out.push(((c - 1) % 10) + 1);
  }
  return out;
}

