function fairTens(rolls: number[]): number[] {
  let pos = 0;
  const rand7 = () => rolls[pos++];
  const hasPair = () => pos + 2 <= rolls.length;
  const rand10 = (): number => {
    while (hasPair()) {
      const row = rand7(), col = rand7();
      const c = (row - 1) * 7 + col;
      if (c <= 40) return ((c - 1) % 10) + 1;
    }
    return -1; // stream ran out
  };
  const out: number[] = [];
  for (let v = rand10(); v !== -1; v = rand10()) out.push(v);
  return out;
}

