class Solution:
    def fairTens(self, rolls: List[int]) -> List[int]:
        it = iter(rolls)
        pairs = len(rolls) // 2

        def rand7():
            return next(it)

        def rand10():
            nonlocal pairs
            while pairs > 0:
                pairs -= 1
                c = (rand7() - 1) * 7 + rand7()
                if c <= 40:
                    return (c - 1) % 10 + 1
            return -1

        out = []
        v = rand10()
        while v != -1:
            out.append(v)
            v = rand10()
        return out

